"""Generate the embedded PDF logo from the instance PNG (requires Pillow)."""
from io import BytesIO
from pathlib import Path
from PIL import Image

root = Path(__file__).resolve().parent
image = Image.open(root / 'logo.png').convert('RGBA')
image.thumbnail((512, 512))
background = Image.new('RGB', image.size, 'white')
background.paste(image, mask=image.getchannel('A'))
stream = BytesIO()
background.save(stream, format='JPEG', quality=90)
(root / 'receiptLogoData.ts').write_text(
    '// Generated by branding/generate-receipt-logo.py from logo.png.\n'
    f'export const receiptLogoData = {{ width: {image.width}, height: {image.height}, '
    f"jpegHex: '{stream.getvalue().hex()}' }};\n"
)
